INSERT INTO `bot_knowledge_base` (`keyword`, `response_text`) VALUES
('giờ làm việc', 'Chúng tôi làm việc từ 8h sáng đến 20h tối, từ thứ Hai đến thứ Bảy.'),
('địa chỉ cửa hàng', 'Cửa hàng của chúng tôi nằm tại số 123 Đường Thể Thao, Quận 1, TP.HCM.'),
('chính sách hoàn tiền', 'Bạn có thể yêu cầu hoàn tiền trong vòng 30 ngày kể từ ngày mua hàng nếu sản phẩm còn nguyên vẹn và chưa qua sử dụng.'),
('bảng giá', 'Bạn có thể xem bảng giá chi tiết trên trang web của chúng tôi tại mục "Sản phẩm".'),
('liên hệ hỗ trợ', 'Bạn có thể liên hệ với chúng tôi qua email support@sportzone.vn hoặc số điện thoại 0909 123 456 hoặc thông qua các nền tảng mạng xã hội như Facebook, Instagram, Tiktok'),
('cách đặt hàng', 'Bạn có thể đặt hàng qua 3 bước: (1) Thêm sản phẩm vào giỏ hàng, (2) Vào giỏ hàng và bấm Thanh toán, (3) Điền thông tin nhận hàng và xác nhận đơn.'),
('phương thức thanh toán', 'Chúng tôi chấp nhận thanh toán qua thẻ tín dụng, thẻ ghi nợ, chuyển khoản ngân hàng và thanh toán khi nhận hàngchúng tôi hỗ trợ: COD (thanh toán khi nhận hàng), chuyển khoản ngân hàng, Momo, ZaloPay.')